        /// overhead, no auth tokens. This is the recommended approach for Workers.
        /// </summary>
        /// <example>
        /// <code>
        /// HTTP mode
        /// ```typescript
        /// import { OpenFeature } from '@openfeature/server-sdk';
        /// import { FlagshipServerProvider } from '@cloudflare/flagship/server';
        ///
        /// await OpenFeature.setProviderAndWait(
        /// new FlagshipServerProvider({
        /// appId: 'app-abc123',
        /// accountId: 'your-account-id',
        /// authToken: 'your-token',
        /// })
        /// );
        /// </code>
        /// <code>
        /// </code>
        /// </example>
        /// <example>
        /// <code>
        /// Binding mode (Cloudflare Workers)
        /// ```typescript
        /// import { OpenFeature } from '@openfeature/server-sdk';
        /// import { FlagshipServerProvider } from '@cloudflare/flagship/server';
        ///
        /// export default {
        /// async fetch(request: Request, env: { FLAGS: FlagshipBinding }) {
        /// await OpenFeature.setProviderAndWait(
        /// new FlagshipServerProvider({ binding: env.FLAGS })
        /// );
        /// const client = OpenFeature.getClient();
        /// const value = await client.getBooleanValue('my-flag', false);
        /// return new Response(JSON.stringify({ value }));
        /// },
        /// };
        /// </code>
        /// <code>
        /// </code>
        /// </example>
        [<Import("FlagshipServerProvider", "@cloudflare/flagship/server"); EmitConstructor>]
        static member FlagshipServerProvider (options: FlagshipServerProviderOptions) : FSharp.CloudEdge.Runtime.Flagship.Server.FlagshipServerProvider = jsNative
        /// <summary>
        /// Logging hook for debugging flag evaluations
        /// </summary>
        /// <example>
        /// <code>
        /// ```typescript
        /// import { OpenFeature } from '@openfeature/server-sdk';
        /// import { FlagshipServerProvider, LoggingHook } from '@cloudflare/flagship/server';
        ///
        /// const provider = new FlagshipServerProvider({ appId: 'your-app-id', accountId: 'your-account-id' });
        /// await OpenFeature.setProviderAndWait(provider);
        ///
        /// // Add logging hook
        /// OpenFeature.addHooks(new LoggingHook());
        /// </code>
        /// <code>
        /// </code>
        /// </example>
        [<Import("LoggingHook", "@cloudflare/flagship/server"); EmitConstructor>]
        static member LoggingHook (?logger: Server.LoggingHook.Logger) : FSharp.CloudEdge.Runtime.Flagship.Server.LoggingHook = jsNative
        /// <summary>
        /// Telemetry hook for tracking flag evaluations
        /// </summary>
        /// <example>
        /// <code>
        /// ```typescript
        /// import { OpenFeature } from '@openfeature/server-sdk';
        /// import { FlagshipServerProvider, TelemetryHook } from '@cloudflare/flagship/server';
        ///
        /// const telemetryHook = new TelemetryHook((event) =&gt; {
        ///   // Send to your analytics service
        ///   analytics.track('flag_evaluated', event);
        /// });
        ///
        /// OpenFeature.addHooks(telemetryHook);
        /// </code>
        /// <code>
        /// </code>
        /// </example>
        [<Import("TelemetryHook", "@cloudflare/flagship/server"); EmitConstructor>]
        static member TelemetryHook (onEvent: (FSharp.CloudEdge.Runtime.Flagship.Server.TelemetryEvent -> unit)) : FSharp.CloudEdge.Runtime.Flagship.Server.TelemetryHook = jsNative

    module LoggingHook =
        type Logger = delegate of message: string * args: obj[] -> unit

        module After =
            [<Interface>]
            type EvaluationDetails<'T> =
                abstract flagKey: string with get, set
                abstract flagMetadata: Server.LoggingHook.After.EvaluationDetails.FlagMetadata with get, set
                abstract value: 'T with get, set
                abstract variant: string option with get, set
                abstract reason: string option with get, set
                abstract errorCode: ErrorCode option with get, set
                abstract errorMessage: string option with get, set
                [<ParamObject; Emit("$0")>]
                static member Create (flagKey: string, flagMetadata: Server.LoggingHook.After.EvaluationDetails.FlagMetadata, value: 'T, ?variant: string, ?reason: string, ?errorCode: ErrorCode, ?errorMessage: string) : EvaluationDetails<'T> = jsNative

            [<Interface>]
            type HookContext =
                abstract flagKey: string
                abstract defaultValue: obj option
                abstract flagValueType: FlagValueType
                abstract context: Server.LoggingHook.After.HookContext.Context
                abstract clientMetadata: obj
                abstract providerMetadata: obj
                abstract logger: obj
                abstract hookData: obj
                [<ParamObject; Emit("$0")>]
                static member Create (flagKey: string, flagValueType: FlagValueType, context: Server.LoggingHook.After.HookContext.Context, clientMetadata: obj, providerMetadata: obj, logger: obj, hookData: obj, ?defaultValue: obj) : HookContext = jsNative

            module EvaluationDetails =
                type FlagMetadata =
                    [<EmitIndexer>]
                    abstract Item: string -> U3<string, float, bool> with get, set

            module HookContext =
                type Context =
                    /// <summary>
                    /// A string uniquely identifying the subject (end-user, or client service) of a flag evaluation.
                    /// Providers may require this field for fractional flag evaluation, rules, or overrides targeting specific users.
                    /// Such providers may behave unpredictably if a targeting key is not specified at flag resolution.
                    /// </summary>
                    abstract targetingKey: string option
                    [<EmitIndexer>]
                    abstract Item: string -> U6<string, float, bool, obj[], JS.Date, ContextTransformer.ToQueryParams.Context.Item> option

    module TelemetryEvent =
        [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
        type Type =
            | [<CompiledName("error")>] Error
            | [<CompiledName("evaluation")>] Evaluation

/// <summary>
/// Error thrown by <c>FlagshipClient</c> for all abnormal conditions.
/// Carries a <c>code</c> for programmatic handling and an optional <c>cause</c> which
/// is the underlying <c>Response</c> object for HTTP errors, allowing callers to
/// inspect the status code (e.g. to distinguish 404 → <c>FLAG_NOT_FOUND</c>).
/// <br /><br />
/// <c>retryable</c> tells callers whether the failure was transient. The SDK uses it
/// to decide whether to retry; consumers can use it to distinguish
/// "ask again later" (<c>true</c> — 408, 425, 429, 5xx, timeouts, connection
/// failures) from a definitive answer (<c>false</c> — 400, 401, 403, 404, other
/// terminal 4xx, caller aborts, unserializable context). Only a non-retryable
/// failure is safe to treat as authoritative and cache.
/// </summary>
type FlagshipErrorConstructor =
    /// <summary>
    /// Indicates whether the argument provided is a built-in Error instance or not.
    /// </summary>
    abstract isError: error: obj -> bool
    /// <summary>
    /// Creates a <c>.stack</c> property on <c>targetObject</c>, which when accessed returns
    /// a string representing the location in the code at which
    /// <c>Error.captureStackTrace()</c> was called.
    /// <code lang="js">
    /// const myObject = {};
    /// Error.captureStackTrace(myObject);
    /// myObject.stack;  // Similar to `new Error().stack`
    /// </code>
    /// <br /><br />
    /// The first line of the trace will be prefixed with
    /// <c>${myObject.name}: ${myObject.message}</c>.
    /// <br /><br />
    /// The optional <c>constructorOpt</c> argument accepts a function. If given, all frames
    /// above <c>constructorOpt</c>, including <c>constructorOpt</c>, will be omitted from the
    /// generated stack trace.
    /// <br /><br />
    /// The <c>constructorOpt</c> argument is useful for hiding implementation
    /// details of error generation from the user. For instance:
    /// <code lang="js">
    /// function a() {
    ///   b();
    /// }
    ///
    /// function b() {
    ///   c();
    /// }
    ///
    /// function c() {
    ///   // Create an error without stack trace to avoid calculating the stack trace twice.
    ///   const { stackTraceLimit } = Error;
    ///   Error.stackTraceLimit = 0;
    ///   const error = new Error();
    ///   Error.stackTraceLimit = stackTraceLimit;
    ///
    ///   // Capture the stack trace above function b
    ///   Error.captureStackTrace(error, b); // Neither function c, nor b is included in the stack trace
    ///   throw error;
    /// }
    ///
    /// a();
    /// </code>
    /// </summary>
    abstract captureStackTrace: targetObject: obj * ?constructorOpt: JS.Function -> unit
    /// <remarks>@see https://v8.dev/docs/stack-trace-api#customizing-stack-traces</remarks>
    abstract prepareStackTrace: err: exn * stackTraces: obj[] -> obj
    /// <summary>
    /// The <c>Error.stackTraceLimit</c> property specifies the number of stack frames
    /// collected by a stack trace (whether generated by <c>new Error().stack</c> or
    /// <c>Error.captureStackTrace(obj)</c>).
    /// <br /><br />
    /// The default value is <c>10</c> but may be set to any valid JavaScript number. Changes
    /// will affect any stack trace captured _after_ the value has been changed.
    /// <br /><br />
    /// If set to a non-number value, or set to a negative number, stack traces will
    /// not capture any frames.
    /// </summary>
    abstract stackTraceLimit: float with get, set
    /// <summary>
    /// Error thrown by <c>FlagshipClient</c> for all abnormal conditions.
    /// Carries a <c>code</c> for programmatic handling and an optional <c>cause</c> which
    /// is the underlying <c>Response</c> object for HTTP errors, allowing callers to
    /// inspect the status code (e.g. to distinguish 404 → <c>FLAG_NOT_FOUND</c>).
    /// <br /><br />
    /// <c>retryable</c> tells callers whether the failure was transient. The SDK uses it
    /// to decide whether to retry; consumers can use it to distinguish
    /// "ask again later" (<c>true</c> — 408, 425, 429, 5xx, timeouts, connection
    /// failures) from a definitive answer (<c>false</c> — 400, 401, 403, 404, other
    /// terminal 4xx, caller aborts, unserializable context). Only a non-retryable
    /// failure is safe to treat as authoritative and cache.
    /// </summary>
    [<EmitConstructor>]
    abstract Create: message: string * code: FlagshipErrorCode * ?cause: obj * ?retryable: bool -> FlagshipError
